      await syncCatalogTabToSheetNow(auth.siteId);
      json(res, 200, { synced: true });
    } catch (err) {
      json(res, 500, { error: err instanceof Error ? err.message : String(err) });
    }
    return true;
  }

  if (pathname === "/api/inventory/sheet/sync" && method === "POST") {
    const auth = await authenticate(req, res);
    if (!auth) return true;
    const [spreadsheetId, ownerEmail] = await Promise.all([
      getSetting(auth.siteId, SHEET_ID_KEY),
      getSetting(auth.siteId, SHEET_OWNER_KEY),
    ]);
    if (!spreadsheetId || !ownerEmail) {
      json(res, 400, { error: "No Google Sheet attached for this site" });
      return true;
    }
    const sheets = await getAdminSheetsClient(ownerEmail);
    if (!sheets) {
      json(res, 400, {
        error: `The user who attached this sheet (${ownerEmail}) needs to sign in with Google again.`,
      });
      return true;
    }
    const body = await readBodyJson(req);
    const from = asString(body.from);
    const to = asString(body.to);
    const rows = await listComplianceLog(auth.siteId, from, to);
    let appended = 0;
    let failed = 0;
    for (const r of rows) {
      try {
        await appendInventoryRow(
          sheets,
          spreadsheetId,
          "Received",
          INVENTORY_SHEET_HEADERS.Received,
          complianceRowToSheetValues(r),
        );
        appended++;
      } catch (err) {
        logError("[Inventory] sheet sync row failed", err, { scope: "inventory.sheets" });
        failed++;
      }
    }
    json(res, 200, { appended, failed, total: rows.length });
    return true;
  }

  return false;
}

// ─── Sheets helpers ──────────────────────────────────────────

function complianceRowToSheetValues(r: ComplianceLogRow): string[] {
  // Order matches INVENTORY_RECEIVED_HEADERS in google-sheets.ts
  const s = (v: unknown) => (v === null || v === undefined ? "" : String(v));
  return [
    s(r.date),
    s(r.bill_number),
    s(r.vendor),
    s(r.product_name),
    s(r.product_name),
    s(r.hsn_code),
    s(r.unit),
    s(r.pack_size),
    s(r.expected_qty),
    s(r.qty_received),
    s(r.expiry_date),
    s(r.received_by),
    s(r.status),
  ];
}

const SHEET_ID_KEY = "google_sheet_id";
const SHEET_OWNER_KEY = "google_sheet_owner_email";

/**
 * Build a Sheets API client authorized as the given admin user, using
 * their stored Google OAuth refresh token. Returns null if the user
 * has no Google token on file — caller decides whether that's an error.
 */
async function getAdminSheetsClient(adminEmail: string) {
  const db = getOptionalPostgresDb();
  if (!db) return null;
  const rows = await db
    .select({ refresh: users.googleRefreshToken })
    .from(users)
    .where(eq(users.email, adminEmail.trim().toLowerCase()))
    .limit(1);
  const refresh = rows[0]?.refresh ?? null;
  if (!refresh) return null;
  return google.sheets({
    version: "v4",
    auth: buildOAuthClientWithRefreshToken(refresh),
  });
}

/**
 * Snapshot the canonical catalog into the "Catalog" tab. Fire-and-forget
 * from the validate / create paths; full sync is exposed via a button on
 * the dashboard.
 */
/**
 * Push the canonical catalog to the linked Google Sheet, NOW.
 * Most callers should use `syncCatalogTabToSheet` instead, which
 * debounces bursts of triggers (every bill validate, every product
 * create, every field registration) into a single push and so avoids
 * the Sheets `Read requests per minute per user` quota.
 */
async function syncCatalogTabToSheetNow(siteId: string): Promise<void> {
  const [spreadsheetId, ownerEmail] = await Promise.all([
    getSetting(siteId, SHEET_ID_KEY),
    getSetting(siteId, SHEET_OWNER_KEY),
  ]);
  if (!spreadsheetId || !ownerEmail) return;
  const sheets = await getAdminSheetsClient(ownerEmail);
  if (!sheets) return;
  const rows = await listCatalogForSheet(siteId);
  const sheetRows = rows.map((r) => [
    r.canonical_name,
    r.category ?? "",
    r.unit,
    String(r.pack_size),
    r.last_price != null ? String(r.last_price) : "",
    r.barcodes ?? "",
    r.hsn_code ?? "",
  ]);
  await replaceSheetTab(
    sheets,
    spreadsheetId,
    "Catalog",
    INVENTORY_SHEET_HEADERS.Catalog,
    sheetRows,
  );
}

// Debounce per site: every write path calls syncCatalogTabToSheet, but
// we only actually push to Sheets DEBOUNCE_MS after the last call. Burst
// of 30 validations → one Sheets write, not thirty. Critical to staying
// under Sheets' 60 reads/min/user quota.
const CATALOG_SYNC_DEBOUNCE_MS = 15_000;
const pendingCatalogSync = new Map<string, ReturnType<typeof setTimeout>>();

function syncCatalogTabToSheet(siteId: string): Promise<void> {
  const existing = pendingCatalogSync.get(siteId);
  if (existing) clearTimeout(existing);
  const handle = setTimeout(() => {
    pendingCatalogSync.delete(siteId);
    void syncCatalogTabToSheetNow(siteId).catch((err) => {
      logError("[Inventory] debounced catalog sync failed", err, {
        scope: "inventory.sheets",
      });
    });
  }, CATALOG_SYNC_DEBOUNCE_MS);
  pendingCatalogSync.set(siteId, handle);
  return Promise.resolve();
}

async function appendComplianceRow(siteId: string, receiptId: string): Promise<void> {
  // Granular step-by-step logging to pinpoint which call throws. The
  // outer try/catch in the receipts route only logs "Sheet append
  // failed" — it can't tell us whether it was getSetting, the SELECT,
  // drizzle, or the actual Sheets API.
  /* eslint-disable no-console */
  let step: string = "init";
  try {
    step = "getSetting(SHEET_ID_KEY)";
    const spreadsheetId = await getSetting(siteId, SHEET_ID_KEY);
    step = "getSetting(SHEET_OWNER_KEY)";
    const ownerEmail = await getSetting(siteId, SHEET_OWNER_KEY);
    if (!spreadsheetId || !ownerEmail) {
      console.warn(`[Inventory] Received append skipped (no sheet attached): site=${siteId}, receipt=${receiptId}`);
      return;
    }

    step = "getAdminSheetsClient";
    const sheets = await getAdminSheetsClient(ownerEmail);
    if (!sheets) {
      console.warn(`[Inventory] Received append skipped (owner Google token missing): owner=${ownerEmail}, receipt=${receiptId}`);
      return;
    }

    step = "getComplianceLogForReceipt";
    const row = await getComplianceLogForReceipt(siteId, receiptId);
    if (!row) {
      console.warn(`[Inventory] Received append skipped (compliance row not found): site=${siteId}, receipt=${receiptId}`);
      return;
    }

    step = "appendInventoryRow(Received)";
    console.log(`[Inventory] Received append → "${row.product_name}" qty=${row.qty_received} (receipt=${receiptId})`);
    await appendInventoryRow(
      sheets,
      spreadsheetId,
      "Received",
      INVENTORY_SHEET_HEADERS.Received,
      complianceRowToSheetValues(row),
    );
  } catch (err) {
    // Re-throw so the outer catch still logs through logError(); but
    // first emit a step label so we see WHICH call blew up.
    console.error(`[Inventory] Received append failed at step "${step}":`, err instanceof Error ? err.message : String(err));
    throw err;
  }
  /* eslint-enable no-console */
}

