export function getCurrentISTDate(): string {
  return formatDateInIST(new Date());
}

export function getRelativeISTDate(days: number): string {
  const today = parsePlainAppTimestamp(getCurrentISTDate());
  if (!today) {
    return "";
  }

  const shifted = new Date(today.getTime() + (days * 24 * 60 * 60 * 1000));
  return formatDateInIST(shifted);
}

export function getCurrentISTDateTime(): string {
  return formatDateTimeInIST(new Date());
}

export function formatDateInIST(input: TimestampInput): string {
  const parts = getDateTimeParts(input);
  if (!parts) {
    return "";
  }

  return `${parts.year}-${parts.month}-${parts.day}`;
}

export function formatTimeInIST(input: TimestampInput): string {
  const parts = getDateTimeParts(input);
  if (!parts) {
    return "";
  }

  return `${parts.hour}:${parts.minute}:${parts.second}`;
}

export function formatClockTimeInIST(input: TimestampInput): string {
  const date = normalizeToDate(input);
  if (!date) {
    return "";
  }

  return getFormatter("en-IN", {
    hour: "2-digit",
    minute: "2-digit",
  }).format(date);
}

