254	  siteId: string,
255	  receiptId: string,
256	): Promise<ComplianceLogRow | null> {
257	  const db = await getDb();
258	  const result = await db.execute({
259	    sql: `
260	      SELECT
261	        r.scanned_at,
262	        to_char(r.scanned_at, 'YYYY-MM-DD') AS date,
263	        io.vendor AS vendor,
264	        io.bill_number AS bill_number,
265	        COALESCE(r.product_id, oi.product_id) AS product_id,
266	        COALESCE(cp.canonical_name, r.product_name) AS product_name,
267	        oi.bill_item_name AS bill_item_name,
268	        cp.category AS category,
269	        COALESCE(cp.hsn_code, oi.hsn_code) AS hsn_code,
270	        cp.unit AS unit,
271	        cp.pack_size AS pack_size,
272	        r.qty AS qty_received,
273	        oi.expected_qty AS expected_qty,
274	        oi.unit_rate AS unit_rate,
275	        (r.qty * COALESCE(oi.unit_rate, 0)) AS line_value,
276	        r.expiry_date AS expiry_date,
277	        COALESCE(g.name, r.guard_id) AS received_by,
278	        -- Flagged = the guard explicitly raised a mismatch flag at the
279	        -- gate (qty mismatch, bad expiry). Pure qty vs expected was
280	        -- misleading for partial deliveries.
281	        -- (Historical note: this comment used to contain an apostrophe
282	        -- which broke the driver placeholder normalizer; see comments
283	        -- in lib/database.ts replaceQuestionPlaceholders for details.)
284	        CASE WHEN r.flagged THEN 'Flagged' ELSE 'OK' END AS status
285	      FROM inventory_receipts r
286	      LEFT JOIN inventory_order_items oi ON oi.id = r.order_item_id
287	      LEFT JOIN inventory_orders io ON io.id = r.order_id
288	      LEFT JOIN canonical_products cp ON cp.product_id = COALESCE(r.product_id, oi.product_id)
289	      LEFT JOIN guards g ON g.id = r.guard_id
290	      WHERE r.id = ? AND r.site_id = ?
291	      LIMIT 1
292	    `,
293	    args: [receiptId, siteId],
294	  });
295	  const row = (result.rows[0] as unknown as ComplianceLogRow | undefined) ?? null;
296	  return row;
297	}
