323	        r.qty AS qty_received,
324	        oi.expected_qty AS expected_qty,
325	        oi.unit_rate AS unit_rate,
326	        (r.qty * COALESCE(oi.unit_rate, 0)) AS line_value,
327	        r.expiry_date AS expiry_date,
328	        COALESCE(g.name, r.guard_id) AS received_by,
329	        -- Flagged = guard explicitly raised a mismatch flag at the
330	        -- gate (qty mismatch, bad expiry, etc.). Pure qty vs expected
331	        -- was misleading for partial deliveries.
332	        --   IMPORTANT: no apostrophes in SQL comments here (see notes in
333	        --   getComplianceLogForReceipt above for the placeholder bug).
334	        CASE WHEN r.flagged THEN 'Flagged' ELSE 'OK' END AS status
335	      FROM inventory_receipts r
336	      LEFT JOIN inventory_order_items oi ON oi.id = r.order_item_id
337	      LEFT JOIN inventory_orders io ON io.id = r.order_id
338	      LEFT JOIN canonical_products cp ON cp.product_id = COALESCE(r.product_id, oi.product_id)
339	      LEFT JOIN guards g ON g.id = r.guard_id
340	      WHERE ${conds.join(' AND ')}
341	      ORDER BY r.scanned_at DESC
342	    `,
343	    args,
344	  });
345	  return result.rows as unknown as ComplianceLogRow[];
