      SELECT
        r.scanned_at,
        to_char(r.scanned_at, 'YYYY-MM-DD') AS date,
        io.vendor AS vendor,
        io.bill_number AS bill_number,
        COALESCE(r.product_id, oi.product_id) AS product_id,
        COALESCE(cp.canonical_name, r.product_name) AS product_name,
        oi.bill_item_name AS bill_item_name,
        cp.category AS category,
        COALESCE(cp.hsn_code, oi.hsn_code) AS hsn_code,
        cp.unit AS unit,
        cp.pack_size AS pack_size,
        r.qty AS qty_received,
        oi.expected_qty AS expected_qty,
        oi.unit_rate AS unit_rate,
        (r.qty * COALESCE(oi.unit_rate, 0)) AS line_value,
        r.expiry_date AS expiry_date,
        COALESCE(g.name, r.guard_id) AS received_by,
        -- Flagged = the guard explicitly raised a mismatch flag at the
        -- gate (qty mismatch, bad expiry). Pure qty vs expected was
        -- misleading for partial deliveries.
        -- (Historical note: this comment used to contain an apostrophe
        -- which broke the driver placeholder normalizer; see comments
        -- in lib/database.ts replaceQuestionPlaceholders for details.)
        CASE WHEN r.flagged THEN 'Flagged' ELSE 'OK' END AS status
      FROM inventory_receipts r
      LEFT JOIN inventory_order_items oi ON oi.id = r.order_item_id
      LEFT JOIN inventory_orders io ON io.id = r.order_id
      LEFT JOIN canonical_products cp ON cp.product_id = COALESCE(r.product_id, oi.product_id)
      LEFT JOIN guards g ON g.id = r.guard_id
      WHERE r.id = ? AND r.site_id = ?
      LIMIT 1
    `,
    args: [receiptId, siteId],
  });
  const row = (result.rows[0] as unknown as ComplianceLogRow | undefined) ?? null;
  return row;
}

export async function listComplianceLog(
  siteId: string,
  fromDate?: string | null,
  toDate?: string | null,
): Promise<ComplianceLogRow[]> {
  const db = await getDb();
  const conds: string[] = ['r.site_id = ?'];
  const args: (string | number | null)[] = [siteId];
  if (fromDate) { conds.push('r.scanned_at >= ?'); args.push(fromDate); }
  if (toDate) { conds.push('r.scanned_at <= ?'); args.push(toDate); }
  const result = await db.execute({
    sql: `
      SELECT
        r.scanned_at,
        to_char(r.scanned_at, 'YYYY-MM-DD') AS date,
        io.vendor AS vendor,
        io.bill_number AS bill_number,
        COALESCE(r.product_id, oi.product_id) AS product_id,
        COALESCE(cp.canonical_name, r.product_name) AS product_name,
        oi.bill_item_name AS bill_item_name,
        cp.category AS category,
        COALESCE(cp.hsn_code, oi.hsn_code) AS hsn_code,
        cp.unit AS unit,
        cp.pack_size AS pack_size,
        r.qty AS qty_received,
        oi.expected_qty AS expected_qty,
        oi.unit_rate AS unit_rate,
        (r.qty * COALESCE(oi.unit_rate, 0)) AS line_value,
        r.expiry_date AS expiry_date,
        COALESCE(g.name, r.guard_id) AS received_by,
        -- Flagged = guard explicitly raised a mismatch flag at the
        -- gate (qty mismatch, bad expiry, etc.). Pure qty vs expected
        -- was misleading for partial deliveries.
        --   IMPORTANT: no apostrophes in SQL comments here (see notes in
        --   getComplianceLogForReceipt above for the placeholder bug).
        CASE WHEN r.flagged THEN 'Flagged' ELSE 'OK' END AS status
      FROM inventory_receipts r
      LEFT JOIN inventory_order_items oi ON oi.id = r.order_item_id
      LEFT JOIN inventory_orders io ON io.id = r.order_id
      LEFT JOIN canonical_products cp ON cp.product_id = COALESCE(r.product_id, oi.product_id)
      LEFT JOIN guards g ON g.id = r.guard_id
      WHERE ${conds.join(' AND ')}
      ORDER BY r.scanned_at DESC
    `,
    args,
  });
  return result.rows as unknown as ComplianceLogRow[];
}

