let _sheetsClient: sheets_v4.Sheets | null = null;

async function getSheetsClient(): Promise<sheets_v4.Sheets | null> {
  if (_sheetsClient) return _sheetsClient;

  const config = getConfig();
  if (!config) {
    console.warn('⚠️ [Sheets] GOOGLE_SHEETS_ID or GOOGLE_SERVICE_ACCOUNT_KEY_PATH not set — export disabled');
    return null;
  }

  try {
    let keyFile: Record<string, unknown>;
    if (config.keyJson) {
      keyFile = JSON.parse(Buffer.from(config.keyJson, 'base64').toString('utf-8'));
    } else {
      keyFile = JSON.parse(readFileSync(config.keyPath!, 'utf-8'));
    }
    const auth = new google.auth.GoogleAuth({
      credentials: keyFile,
      scopes: ['https://www.googleapis.com/auth/spreadsheets'],
    });

    _sheetsClient = google.sheets({ version: 'v4', auth });
    return _sheetsClient;
  } catch (error) {
    console.error('❌ [Sheets] Auth failed:', error);
    return null;
  }
}

/**
 * Auth-only sheets client. Loads the service-account credential without
 * requiring GOOGLE_SHEETS_ID — so callers that supply their own
 * spreadsheetId (e.g. per-site attached sheets) can still authenticate.
 */
let _authOnlySheetsClient: sheets_v4.Sheets | null = null;
export async function getAuthOnlySheetsClient(): Promise<sheets_v4.Sheets | null> {
  if (_authOnlySheetsClient) return _authOnlySheetsClient;
  if (_sheetsClient) return _sheetsClient;

  const keyJson = process.env.GOOGLE_SERVICE_ACCOUNT_KEY_JSON;
  const keyPath = process.env.GOOGLE_SERVICE_ACCOUNT_KEY_PATH;
  if (!keyJson && !keyPath) return null;

  try {
    const keyFile = keyJson
      ? JSON.parse(Buffer.from(keyJson, 'base64').toString('utf-8'))
      : JSON.parse(readFileSync(keyPath!, 'utf-8'));
    const auth = new google.auth.GoogleAuth({
      credentials: keyFile,
      scopes: ['https://www.googleapis.com/auth/spreadsheets'],
    });
    _authOnlySheetsClient = google.sheets({ version: 'v4', auth });
    return _authOnlySheetsClient;
  } catch (error) {
    console.error('❌ [Sheets] Auth-only client failed:', error);
    return null;
  }
}

