async function ensureSheet(sheets: sheets_v4.Sheets, spreadsheetId: string, title: string): Promise<void> {
  try {
    const meta = await sheets.spreadsheets.get({ spreadsheetId });
    const exists = meta.data.sheets?.some(s => s.properties?.title === title);
    if (!exists) {
      await sheets.spreadsheets.batchUpdate({
        spreadsheetId,
        requestBody: {
          requests: [{ addSheet: { properties: { title } } }],
        },
      });
      console.log(`📊 [Sheets] Created tab: "${title}"`);
    }
  } catch (error) {
    console.error(`❌ [Sheets] Failed to ensure sheet "${title}":`, error);
  }
}

/**
 * Clear and write data to a sheet tab.
 */
async function writeToSheet(
  sheets: sheets_v4.Sheets,
  spreadsheetId: string,
  sheetTitle: string,
  headers: string[],
  rows: (string | number | null)[][],
): Promise<void> {
  // Clear existing data
  await sheets.spreadsheets.values.clear({
    spreadsheetId,
    range: formatSheetRange(sheetTitle, 'A:ZZZ'),
  });

  // Write headers + data
  const values = [headers, ...rows];
  await sheets.spreadsheets.values.update({
    spreadsheetId,
    range: formatSheetRange(sheetTitle, 'A1'),
    valueInputOption: 'USER_ENTERED',
    requestBody: { values },
  });
}

