/**
 * IST date formatted as "DD-MMM-YYYY" (e.g. "03-Jun-2026"). Designed for
 * cells in Google Sheets — Sheets parses this as a date and keeps the
 * display format matching the input style instead of showing the date
 * serial number (the "46176" bug).
 */
export function formatShortDateInIST(input: TimestampInput): string {
  const date = normalizeToDate(input);
  if (!date) {
    return "";
  }
  // en-GB gives day-month-year ordering; force "-" as separator to match
  // Sheets' dd-mmm-yyyy number-format pattern.
  return getFormatter("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "Asia/Kolkata",
  })
    .format(date)
    .replace(/\s+/g, "-");
}

