input.new_string:
function complianceRowToSheetValues(r: ComplianceLogRow): string[] {
  // Order matches INVENTORY_RECEIVED_HEADERS in google-sheets.ts.
  // - `r.date` is YYYY-MM-DD; reformat to dd-MMM-yyyy so Sheets renders
  //   it as a date instead of the serial-number (the "46176" bug).
  // - scanned_at is stored UTC in the DB; we display IST everywhere.
  const s = (v: unknown) => (v === null || v === undefined ? "" : String(v));
  return [
    r.date ? formatShortDateInIST(r.date) : "",
    s(r.bill_number),
    s(r.vendor),
    s(r.product_name),
    s(r.product_name),
    s(r.hsn_code),
    s(r.unit),
    s(r.pack_size),
    s(r.expected_qty),
    s(r.qty_received),
    s(r.expiry_date),
    s(r.received_by),
    s(r.status),
    r.scanned_at ? formatDateTimeInIST(r.scanned_at) : "",
  ];
}

