1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import { Bell, type LucideIcon, HandCoins, Package, RefreshCw, ScanLine, Settings as SettingsIcon, Truck } from 'lucide-react-native';
3	import { QueueBadge } from '../components/QueueBadge';
4	import React, { useCallback, useEffect, useState } from 'react';
5	import { ScrollView, StyleSheet, View } from 'react-native';
6	import { SafeAreaView } from 'react-native-safe-area-context';
7	import { Button, Card, IconButton, Skeleton, spacing, Text } from '../../../design';
8	import { useTheme } from '../../../theme';
9	import { getSession } from '../../../auth/session';
10	import { listOpenOrders } from '../../../db/orders';
11	import { listProducts } from '../../../db/products';
12	import { listLowOrOut } from '../../../db/stock';
13	import { useT } from '../../../i18n';
14	import { RootStackParamList } from '../../../navigation/types';
15	
16	type Props = NativeStackScreenProps<RootStackParamList, 'Home'>;
17	
18	type Stats = {
19	  orders: number;
20	  products: number;
21	  alerts: number;
22	};
23	
24	export function HomeScreen({ navigation }: Props) {
25	  const t = useT();
26	  const { palette } = useTheme();
27	  const [stats, setStats] = useState<Stats | null>(null);
28	
29	  const load = useCallback(async () => {
30	    const [p, o, a] = await Promise.all([listProducts(1000), listOpenOrders(), listLowOrOut()]);
31	    setStats({ products: p.length, orders: o.length, alerts: a.length });
32	  }, []);
33	
34	  useEffect(() => {
35	    load();
36	    const unsub = navigation.addListener('focus', load);
37	    return unsub;
38	  }, [navigation, load]);
39	
40	  return (
41	    <SafeAreaView edges={['top']} style={[styles.safe, { backgroundColor: palette.background }]}>
42	      <ScrollView contentContainerStyle={styles.scroll}>
43	        <View style={styles.header}>
44	          <View style={styles.headerRow}>
45	            <View style={{ flex: 1 }}>
46	              <Text variant="headlineMedium">
47	                {t('greeting')}, {getSession()?.guardName ?? ''}
48	              </Text>
49	              <Text variant="bodyLarge" color={palette.onSurfaceVariant} style={{ marginTop: spacing.xs }}>
50	                {t('appName')}
51	              </Text>
52	            </View>
53	            <IconButton Icon={SettingsIcon} onPress={() => navigation.navigate('Settings')} />
54	          </View>
55	        </View>
56	
57	        <View style={styles.primary}>
58	          <Button
59	            label={t('startScanning')}
60	            leadingIcon={<ScanLine size={28} color={palette.onPrimary} strokeWidth={2.4} />}
61	            size="xl"
62	            fullWidth
63	            onPress={() => navigation.navigate('Scanner')}
64	          />
65	          <Text
66	            variant="bodyMedium"
67	            color={palette.onSurfaceVariant}
68	            style={{ textAlign: 'center', marginTop: spacing.md }}
69	          >
70	            {t('scanItem')}.
71	          </Text>
72	        </View>
73	
74	        <View style={styles.tilesRow}>
75	          <Tile
76	            label={t('receiving')}
77	            value={stats?.orders}
78	            loading={!stats}
79	            sub={t('expectedToday')}
80	            Icon={Truck}
81	            onPress={() => navigation.navigate('Orders')}
82	          />
83	          <Tile
84	            label={t('stock')}
85	            value={stats?.products}
86	            loading={!stats}
87	            sub={t('stockSub')}
88	            Icon={Package}
89	            onPress={() => navigation.navigate('Stock')}
90	          />
91	        </View>
92	
93	        <View style={styles.tilesRow}>
94	          <Tile
95	            label={t('dispense')}
96	            sub={t('dispenseSub')}
97	            Icon={HandCoins}
98	            onPress={() => navigation.navigate('Dispense')}
99	          />
100	          <Tile
101	            label={t('alerts')}
102	            value={stats?.alerts || undefined}
103	            loading={!stats}
