1	import { NativeStackScreenProps } from '@react-navigation/native-stack';
2	import React, { useCallback, useEffect, useMemo, useState } from 'react';
3	import { FlatList, RefreshControl, StyleSheet, View } from 'react-native';
4	import { AppBar, Button, Card, Skeleton, spacing, StatusPill, Text } from '../../../design';
5	import { getDb } from '../../../db/database';
6	import { OutboxRow } from '../../../db/outbox';
7	import { useT } from '../../../i18n';
8	import { RootStackParamList } from '../../../navigation/types';
9	import { flushOnce, getLastSyncAt } from '../../../sync/syncService';
10	import { useTheme } from '../../../theme';
11	
12	type Props = NativeStackScreenProps<RootStackParamList, 'Outbox'>;
13	
14	const STATUS_LABEL: Record<string, string> = {
15	  queued: 'Waiting',
16	  sending: 'Sending…',
17	  failed: 'Failed',
18	};
19	
20	const TONE: Record<string, 'warn' | 'danger' | 'neutral'> = {
21	  sending: 'warn',
22	  failed: 'danger',
23	  queued: 'neutral',
24	};
25	
26	/** Parse payload JSON to produce a human-readable description */
27	function describeItem(kind: string, payloadStr: string): string {
28	  try {
29	    const p = JSON.parse(payloadStr);
30	    const name = p.product_name ?? p.name ?? '';
31	    const qty = p.qty ?? '';
32	    switch (kind) {
33	      case 'receipt':
34	        return `Received ${qty}× ${name}`.trim();
35	      case 'product_registration':
36	        return `New product: ${name}`.trim();
37	      case 'issue':
38	      case 'dispense':
39	        return `Dispensed ${qty}× ${name}`.trim();
40	      case 'reorder_request':
41	        return `Reorder: ${name}`.trim();
42	      case 'mismatch_flag':
43	        return `Mismatch: ${p.received_total ?? '?'} vs ${p.expected ?? '?'} expected`;
44	      default:
45	        return kind;
46	    }
47	  } catch {
48	    return kind;
49	  }
50	}
51	
52	function timeAgo(ts: number): string {
53	  const diff = Date.now() - ts;
54	  const minutes = Math.floor(diff / 60000);
55	  if (minutes < 1) return 'Just now';
56	  if (minutes < 60) return `${minutes} min ago`;
57	  const hours = Math.floor(minutes / 60);
58	  if (hours < 24) return `${hours}h ago`;
59	  return `${Math.floor(hours / 24)}d ago`;
60	}
61	
62	export function OutboxScreen({ navigation }: Props) {
63	  const t = useT();
64	  const { palette } = useTheme();
65	  const [rows, setRows] = useState<OutboxRow[]>([]);
66	  const [busy, setBusy] = useState(false);
67	  const [initialLoading, setInitialLoading] = useState(true);
68	  const [syncResult, setSyncResult] = useState<string | null>(null);
69	
70	  const load = useCallback(async () => {
71	    const db = await getDb();
72	
73	    // Delete all sent items immediately — only show what's pending
74	    await db.runAsync(`DELETE FROM outbox WHERE status = 'sent'`);
75	
76	    setRows(
77	      await db.getAllAsync<OutboxRow>(
78	        `SELECT * FROM outbox WHERE status != 'sent'
79	         ORDER BY CASE status WHEN 'failed' THEN 0 WHEN 'sending' THEN 1 ELSE 2 END, created_at DESC
80	         LIMIT 200`,
81	      ),
82	    );
83	    setInitialLoading(false);
84	  }, []);
85	
86	  useEffect(() => {
87	    load();
88	  }, [load]);
89	
90	  const failedCount = useMemo(() => rows.filter((r) => r.status === 'failed').length, [rows]);
91	
92	  const lastSyncAt = getLastSyncAt();
93	
94	  const sync = async () => {
95	    setBusy(true);
96	    setSyncResult(null);
97	    try {
98	      const result = await flushOnce();
99	      await load();
100	      if (result.sent > 0 || result.failed > 0) {
101	        setSyncResult(`Synced ${result.sent} item${result.sent === 1 ? '' : 's'}${result.failed > 0 ? `, ${result.failed} failed` : ''}`);
102	      } else {
103	        setSyncResult('All synced ✓');
104	      }
105	    } catch {
106	      setSyncResult('Sync failed — check connection');
107	    } finally {
108	      setBusy(false);
109	    }
110	  };
111	
112	  return (
113	    <View style={[styles.safe, { backgroundColor: palette.background }]}>
114	      <AppBar title={t('syncQueue')} onBack={() => navigation.goBack()} />
115	
116	      {/* Status bar */}
117	      <View style={styles.statusBar}>
118	        <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
119	          {rows.length === 0
120	            ? 'All synced ✓'
121	            : `${rows.length} item${rows.length === 1 ? '' : 's'} waiting`}
122	          {failedCount > 0 ? ` · ${failedCount} failed` : ''}
123	          {lastSyncAt ? `  ·  Last sync: ${timeAgo(lastSyncAt)}` : ''}
124	        </Text>
125	        {syncResult && (
126	          <Text
127	            variant="bodyMedium"
128	            color={failedCount > 0 ? palette.error : palette.primary}
129	          >
130	            {syncResult}
131	          </Text>
132	        )}
133	      </View>
134	
135	      {initialLoading && rows.length === 0 ? (
136	        <View style={styles.list}>
137	          {[0, 1, 2].map((i) => (
138	            <View key={i} style={{ marginBottom: spacing.sm }}>
139	              <Card tone="filled" padding="lg">
140	                <View style={styles.rowHead}>
141	                  <Skeleton width="40%" height={18} />
142	                  <Skeleton width={64} height={20} rounded="pill" />
143	                </View>
144	                <View style={{ height: spacing.xs }} />
145	                <Skeleton width="65%" height={14} />
146	              </Card>
147	            </View>
148	          ))}
149	        </View>
150	      ) : (
151	      <FlatList
152	        data={rows}
153	        keyExtractor={(r) => r.id}
154	        contentContainerStyle={styles.list}
155	        refreshControl={<RefreshControl refreshing={busy} onRefresh={sync} tintColor={palette.primary} />}
156	        ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}
157	        renderItem={({ item }) => (
158	          <Card tone="filled" padding="lg">
159	            <View style={styles.rowHead}>
160	              <Text variant="titleMedium" style={{ flex: 1 }}>
161	                {describeItem(item.kind, item.payload)}
162	              </Text>
163	              <StatusPill label={STATUS_LABEL[item.status] ?? item.status} tone={TONE[item.status] ?? 'neutral'} />
164	            </View>
165	            <Text variant="bodyMedium" color={palette.onSurfaceVariant} style={{ marginTop: spacing.xs }}>
166	              {timeAgo(item.created_at)}
167	              {item.attempts > 0 ? ` · ${item.attempts} attempt${item.attempts === 1 ? '' : 's'}` : ''}
168	            </Text>
169	            {item.last_error ? (
170	              <Text variant="bodyMedium" color={palette.error} style={{ marginTop: spacing.xs }} numberOfLines={2}>
171	                {item.last_error}
172	              </Text>
173	            ) : null}
174	          </Card>
175	        )}
176	        ListEmptyComponent={
177	          <View style={styles.empty}>
