import { nanoid } from 'nanoid/non-secure';
import { getDb, now } from './database';

export type OutboxKind =
  | 'receipt'
  | 'product_registration'
  | 'issue'
  | 'dispense'
  | 'reorder_request'
  | 'mismatch_flag'
  | 'learn_barcode';

export type OutboxRow = {
  id: string;
  kind: OutboxKind;
  payload: string;
  status: 'queued' | 'sending' | 'sent' | 'failed';
  attempts: number;
  last_error: string | null;
  created_at: number;
  updated_at: number;
};

export async function enqueue(kind: OutboxKind, payload: object): Promise<string> {
  const db = await getDb();
  const id = `out_${nanoid(12)}`;
  const ts = now();
  await db.runAsync(
    `INSERT INTO outbox (id, kind, payload, status, attempts, created_at, updated_at)
     VALUES (?, ?, ?, 'queued', 0, ?, ?)`,
    [id, kind, JSON.stringify(payload), ts, ts]
  );
  return id;
}

export async function pendingCount(): Promise<number> {
  const db = await getDb();
  const row = await db.getFirstAsync<{ c: number }>(
    `SELECT COUNT(*) as c FROM outbox WHERE status IN ('queued', 'failed')`
  );
  return row?.c ?? 0;
}

export async function nextBatch(limit: number): Promise<OutboxRow[]> {
  const db = await getDb();
  return db.getAllAsync<OutboxRow>(
    `SELECT * FROM outbox WHERE status IN ('queued', 'failed')
     ORDER BY created_at ASC LIMIT ?`,
    [limit]
  );
}

export async function markSending(id: string): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `UPDATE outbox SET status = 'sending', last_error = NULL, updated_at = ? WHERE id = ?`,
    [now(), id]
  );
}

/**
 * Reset rows orphaned mid-flight (process killed, OS reclaim, crash)
 * back to 'queued' so the next flush picks them up. Without this they
 * stay 'sending' forever — `nextBatch` only selects queued/failed.
 */
export async function recoverOrphanedSending(): Promise<number> {
  const db = await getDb();
  const result = await db.runAsync(
    `UPDATE outbox SET status = 'queued', updated_at = ? WHERE status = 'sending'`,
    [now()]
  );
  return result.changes ?? 0;
}

export async function markSent(id: string): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `UPDATE outbox SET status = 'sent', updated_at = ? WHERE id = ?`,
    [now(), id]
  );
}

export async function markFailed(id: string, err: string): Promise<void> {
  const db = await getDb();
  await db.runAsync(
    `UPDATE outbox SET status = 'failed', attempts = attempts + 1, last_error = ?, updated_at = ? WHERE id = ?`,
    [err.slice(0, 500), now(), id]
  );
}

import { NativeStackScreenProps } from '@react-navigation/native-stack';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Alert, FlatList, RefreshControl, StyleSheet, View } from 'react-native';
import { AppBar, Button, Card, Skeleton, spacing, StatusPill, Text } from '../../../design';
import { getDb } from '../../../db/database';
import { OutboxRow } from '../../../db/outbox';
import { useT } from '../../../i18n';
import { RootStackParamList } from '../../../navigation/types';
import { flushOnce, getLastSyncAt } from '../../../sync/syncService';
import { useTheme } from '../../../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'Outbox'>;

// Internal plumbing kinds the user shouldn't see in the queue. They
// still sync in the background; they just don't appear in the list
// or count toward "items waiting".
const HIDDEN_KINDS: readonly string[] = ['learn_barcode'];

const STATUS_LABEL: Record<string, string> = {
  queued: 'Waiting',
  sending: 'Sending…',
  failed: 'Failed',
};

const TONE: Record<string, 'warn' | 'danger' | 'neutral'> = {
  sending: 'warn',
  failed: 'danger',
  queued: 'neutral',
};

/** Parse payload JSON to produce a human-readable description */
function describeItem(kind: string, payloadStr: string): string {
  try {
    const p = JSON.parse(payloadStr);
    const name = p.product_name ?? p.name ?? '';
    const qty = p.qty ?? '';
    switch (kind) {
      case 'receipt':
        return `Received ${qty}× ${name}`.trim();
      case 'product_registration':
        return `New product: ${name}`.trim();
      case 'issue':
      case 'dispense':
        return `Dispensed ${qty}× ${name}`.trim();
      case 'reorder_request':
        return `Reorder: ${name}`.trim();
      case 'mismatch_flag':
        return `Mismatch: ${p.received_total ?? '?'} vs ${p.expected ?? '?'} expected`;
      default:
        return kind;
    }
  } catch {
    return kind;
  }
}

function timeAgo(ts: number): string {
  const diff = Date.now() - ts;
  const minutes = Math.floor(diff / 60000);
  if (minutes < 1) return 'Just now';
  if (minutes < 60) return `${minutes} min ago`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.floor(hours / 24)}d ago`;
}

export function OutboxScreen({ navigation }: Props) {
  const t = useT();
  const { palette } = useTheme();
  const [rows, setRows] = useState<OutboxRow[]>([]);
  const [busy, setBusy] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [syncResult, setSyncResult] = useState<string | null>(null);

  const load = useCallback(async () => {
    const db = await getDb();

    // Delete all sent items immediately — only show what's pending
    await db.runAsync(`DELETE FROM outbox WHERE status = 'sent'`);

    const hiddenList = HIDDEN_KINDS.map(() => '?').join(',');
    setRows(
      await db.getAllAsync<OutboxRow>(
        `SELECT * FROM outbox
         WHERE status != 'sent' AND kind NOT IN (${hiddenList})
         ORDER BY CASE status WHEN 'failed' THEN 0 WHEN 'sending' THEN 1 ELSE 2 END, created_at DESC
         LIMIT 200`,
        HIDDEN_KINDS as string[],
      ),
    );
    setInitialLoading(false);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const failedCount = useMemo(() => rows.filter((r) => r.status === 'failed').length, [rows]);

  const lastSyncAt = getLastSyncAt();

  const clearQueue = () => {
    if (rows.length === 0) return;
    Alert.alert(
      'Clear sync queue?',
      `${rows.length} pending item${rows.length === 1 ? '' : 's'} will be permanently deleted. They will NOT be sent to the server.`,
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Clear',
          style: 'destructive',
          onPress: async () => {
            const db = await getDb();
            await db.runAsync(`DELETE FROM outbox WHERE status != 'sent'`);
            await load();
            setSyncResult('Queue cleared');
          },
        },
      ],
    );
  };

  const sync = async () => {
    setBusy(true);
    setSyncResult(null);
    try {
      const result = await flushOnce();
      await load();
      if (result.sent > 0 || result.failed > 0) {
        setSyncResult(`Synced ${result.sent} item${result.sent === 1 ? '' : 's'}${result.failed > 0 ? `, ${result.failed} failed` : ''}`);
      } else {
        setSyncResult('All synced ✓');
      }
    } catch {
      setSyncResult('Sync failed — check connection');
    } finally {
      setBusy(false);
    }
  };

  return (
    <View style={[styles.safe, { backgroundColor: palette.background }]}>
      <AppBar title={t('syncQueue')} onBack={() => navigation.goBack()} />

      {/* Status bar */}
      <View style={styles.statusBar}>
        <Text variant="bodyMedium" color={palette.onSurfaceVariant}>
          {rows.length === 0
            ? 'All synced ✓'
            : `${rows.length} item${rows.length === 1 ? '' : 's'} waiting`}
          {failedCount > 0 ? ` · ${failedCount} failed` : ''}
          {lastSyncAt ? `  ·  Last sync: ${timeAgo(lastSyncAt)}` : ''}
        </Text>
        {syncResult && (
          <Text
            variant="bodyMedium"
            color={failedCount > 0 ? palette.error : palette.primary}
          >
            {syncResult}
          </Text>
        )}
      </View>

      {initialLoading && rows.length === 0 ? (
        <View style={styles.list}>
          {[0, 1, 2].map((i) => (
            <View key={i} style={{ marginBottom: spacing.sm }}>
              <Card tone="filled" padding="lg">
                <View style={styles.rowHead}>
                  <Skeleton width="40%" height={18} />
                  <Skeleton width={64} height={20} rounded="pill" />
                </View>
                <View style={{ height: spacing.xs }} />
                <Skeleton width="65%" height={14} />
              </Card>
            </View>
          ))}
        </View>
      ) : (
      <FlatList
        data={rows}
